48	class _MeusRegistrosScreenState extends State<MeusRegistrosScreen> {
49	  // RNF01: no loading UI below 300ms — same threshold/`Timer` pattern as
50	  // `BootSplashScreen`.
51	  static const _skeletonThreshold = Duration(milliseconds: 300);
52	
53	  final ScrollController _scrollController = ScrollController();
54	  Timer? _skeletonTimer;
55	  bool _showSkeleton = false;
56	
57	  /// Review fix (round 2, spec-4-4) — guards `_openDetail` against a rapid
58	  /// double-tap on a card pushing `/meus-registros/:id` twice (stacking two
59	  /// detail-route instances); cleared once the pushed route is popped, via
60	  /// `whenComplete` below.
