62	
63	  @override
64	  void initState() {
65	    super.initState();
66	    widget.cubit.loadFirstPage();
67	    _skeletonTimer = Timer(_skeletonThreshold, () {
68	      if (mounted) {
69	        setState(() => _showSkeleton = true);
70	      }
71	    });
72	    _scrollController.addListener(_onScroll);
73	  }
74	
75	  @override
76	  void dispose() {
77	    _skeletonTimer?.cancel();
78	    _scrollController
