91	          '${AppRoutePaths.meusRegistros}/'
92	          '${Uri.encodeComponent(entry.id)}',
93	        )
94	        .whenComplete(() {
95	          if (mounted) {
96	            setState(() => _navigatingToDetail = false);
97	          } else {
