103	  void _onScroll() {
104	    if (!_scrollController.hasClients) {
105	      return;
106	    }
107	    final position = _scrollController.position;
108	    // Pre-fetches a little before the exact end (reusing `spacing2xl`
109	    // purely as a scroll-distance buffer, not a new literal) for a
110	    // smoother scroll-pagination feel; `loadMore()` itself is a no-op once
111	    // there's no further page or a call is already in flight.
112	    if (position.pixels >= position.maxScrollExtent - DesignTokens.spacing2xl) {
113	      widget.cubit.loadMore();
114	    }
115	  }
