407	/// "Hoje"/"Ontem"/`dd/mm/yyyy` — presentation's own job (Code Map: day
408	/// labels aren't the pure `groupEntriesByDate()`'s concern). [date] is
409	/// always already truncated to local midnight (`EntryDateGroup`'s own
410	/// contract).
411	String _dayLabel(DateTime date) {
412	  final now = DateTime.now();
413	  final today = DateTime(now.year, now.month, now.day);
414	  final yesterday = today.subtract(const Duration(days: 1));
415	  if (date == today) {
416	    return 'Hoje';
417	  }
418	  if (date == yesterday) {
419	    return 'Ontem';
420	  }
421	  final day = date.day.toString().padLeft(2, '0');
422	  final month = date.month.toString().padLeft(2, '0');
423	  return '$day/$month/${date.year}';
424	}
