1	import 'dart:async';
2	
3	import 'package:flutter_test/flutter_test.dart';
4	import 'package:fpdart/fpdart.dart';
5	
6	import 'package:cerne/core/failure/failure.dart';
7	import 'package:cerne/core/resource.dart';
8	import 'package:cerne/features/entries/domain/entities/entries_page.dart';
9	import 'package:cerne/features/entries/domain/entities/entry.dart';
10	import 'package:cerne/features/entries/domain/repositories/entries_repository.dart';
11	import 'package:cerne/features/entries/presentation/cubit/entries_search_cubit.dart';
12	
13	Entry _entry(String id) => Entry(
14	  id: id,
15	  content: 'content-$id',
16	  source: EntrySource.manual,
17	  chatMessageId: null,
18	  occurredAt: '2026-01-01T00:00:00Z',
19	  serverRevision: 1,
20	  createdAt: '2026-01-01T00:00:00Z',
21	  updatedAt: '2026-01-01T00:00:00Z',
22	);
23	
24	/// A plain (non-mocktail) fake — same convention
25	/// `meus_registros_cubit_test.dart`'s own fakes use. Needed here because
26	/// several tests (debounce coalescing, stale-result discarding) must
27	/// assert exactly how many times/with what argument `search()` was
28	/// called, and the stale-result tests need to resolve two calls out of
29	/// order — a single static mocktail stub can't express that naturally.
30	class _FakeEntriesRepository implements EntriesRepository {
31	  final List<Either<Failure, List<Entry>>> _results = [];
32	  final List<Completer<Either<Failure, List<Entry>>>> _completers = [];
33	  final List<String> searchCalls = [];
34	
35	  /// When `true`, [search] returns a `Completer`-backed future the test
36	  /// resolves explicitly (via [resolve]) rather than immediately returning
37	  /// a queued result — needed to reproduce a stale in-flight call landing
38	  /// after a newer one has already superseded it.
39	  bool gated = false;
40	
41	  void queueSearch(Either<Failure, List<Entry>> result) {
42	    _results.add(result);
43	  }
44	
45	  void resolve(int callIndex, Either<Failure, List<Entry>> result) {
46	    _completers[callIndex].complete(result);
47	  }
48	
49	  @override
50	  Future<Either<Failure, List<Entry>>> search(String query) {
51	    searchCalls.add(query);
52	    if (gated) {
53	      final completer = Completer<Either<Failure, List<Entry>>>();
54	      _completers.add(completer);
55	      return completer.future;
56	    }
57	    if (_results.isEmpty) {
58	      throw StateError(
59	        'no queued search() result for call #${searchCalls.length}',
60	      );
61	    }
62	    return Future.value(_results.removeAt(0));
63	  }
64	
65	  @override
66	  Future<Either<Failure, Entry>> create({
67	    required String content,
68	    required EntrySource source,
69	    int? mediaDurationSeconds,
70	  }) async => throw UnimplementedError('not expected to be called');
71	
72	  @override
73	  Future<Either<Failure, EntriesPage>> list({
74	    String? cursor,
75	    int limit = 20,
76	  }) async => throw UnimplementedError('not expected to be called');
77	
78	  @override
79	  Future<Either<Failure, Entry>> getById(String id) async =>
80	      throw UnimplementedError('not expected to be called');
81	}
82	
83	/// Collects every state the cubit emits for the duration of [act] — same
84	/// helper/rationale `auth_cubit_test.dart` already documents: this stack
85	/// has no `bloc_test` pin, so this drives [EntriesSearchCubit] through its
86	/// public API only, the same way any other `flutter_bloc` consumer would.
87	Future<List<Resource<List<Entry>>>> _emittedDuring(
88	  EntriesSearchCubit cubit,
89	  FutureOr<void> Function() act,
90	) async {
91	  final emitted = <Resource<List<Entry>>>[];
92	  final subscription = cubit.stream.listen(emitted.add);
93	  await act();
94	  await subscription.cancel();
95	  return emitted;
96	}
97	
98	void main() {
99	  late _FakeEntriesRepository fakeRepository;
100	  late EntriesSearchCubit cubit;
101	
102	  setUp(() {
103	    fakeRepository = _FakeEntriesRepository();
104	    cubit = EntriesSearchCubit(fakeRepository);
105	  });
106	
107	  tearDown(() async {
108	    if (!cubit.isClosed) {
109	      await cubit.close();
110	    }
111	  });
112	
113	  test('starts as ResourceIdle', () {
114	    expect(cubit.state, const ResourceIdle<List<Entry>>());
115	  });
116	
117	  test(
118	    'I/O matrix: "Semantic match" — a successful search emits '
119	    'ResourceLoading then ResourceData with the repository\'s results, '
120	    '300ms after the triggering call',
121	    () async {
122	      fakeRepository.queueSearch(right([_entry('e1')]));
123	
124	      final emitted = await _emittedDuring(cubit, () async {
125	        cubit.onQueryChanged('ansiedade');
126	        await Future<void>.delayed(const Duration(milliseconds: 350));
127	      });
128	
129	      expect(emitted, [
130	        // Not a `const` comparison (Review finding) — `_search()`
131	        // deliberately emits a fresh, non-canonicalized `ResourceLoading`
132	        // each time, so only its runtime type is asserted here.
133	        isA<ResourceLoading<List<Entry>>>(),
134	        isA<ResourceData<List<Entry>>>().having(
135	          (s) => s.data.map((e) => e.id),
136	          'data ids',
137	          ['e1'],
138	        ),
139	      ]);
140	    },
141	  );
142	
143	  test('onQueryChanged trims the raw input before calling search()', () async {
144	    fakeRepository.queueSearch(right([_entry('e1')]));
145	
146	    cubit.onQueryChanged('  ansiedade  ');
147	    await Future<void>.delayed(const Duration(milliseconds: 350));
148	
149	    expect(fakeRepository.searchCalls, ['ansiedade']);
150	  });
151	
152	  test(
153	    'I/O matrix: "Rapid typing" — 5 keystrokes within 300ms fire exactly '
154	    'one entries-search call, for the final value',
155	    () async {
156	      fakeRepository.queueSearch(right([_entry('e1')]));
157	
158	      cubit.onQueryChanged('a');
159	      await Future<void>.delayed(const Duration(milliseconds: 50));
160	      cubit.onQueryChanged('an');
161	      await Future<void>.delayed(const Duration(milliseconds: 50));
162	      cubit.onQueryChanged('ans');
163	      await Future<void>.delayed(const Duration(milliseconds: 50));
164	      cubit.onQueryChanged('ansi');
165	      await Future<void>.delayed(const Duration(milliseconds: 50));
166	      cubit.onQueryChanged('ansiedade');
167	
168	      // Still well within the 300ms window since the last keystroke — no
169	      // call should have fired yet.
170	      await Future<void>.delayed(const Duration(milliseconds: 100));
171	      expect(fakeRepository.searchCalls, isEmpty);
172	
173	      // Past the 300ms debounce window from the final keystroke.
174	      await Future<void>.delayed(const Duration(milliseconds: 250));
175	      expect(fakeRepository.searchCalls, ['ansiedade']);
176	    },
177	  );
178	
179	  test(
180	    'I/O matrix: "Query cleared" — a non-empty query followed by an empty/'
181	    'whitespace one cancels the pending timer and emits ResourceIdle, '
182	    'with no request ever firing',
183	    () async {
184	      final emitted = await _emittedDuring(cubit, () async {
185	        cubit.onQueryChanged('ansiedade');
186	        cubit.onQueryChanged('   ');
187	        await Future<void>.delayed(const Duration(milliseconds: 350));
188	      });
189	
190	      expect(emitted, [const ResourceIdle<List<Entry>>()]);
191	      expect(fakeRepository.searchCalls, isEmpty);
192	    },
193	  );
194	
195	  test(
196	    'I/O matrix: "Offline" — a Failure.networkOffline from the repository '
197	    'emits ResourceError(networkOffline), never a cache fallback',
198	    () async {
199	      fakeRepository.queueSearch(
200	        left(const Failure.networkOffline(message: 'Sem conexão')),
201	      );
202	
